module mealy_101_detector (
    input  logic clk,
    input  logic rst_n,
    input  logic data_in,
    output logic detected
);

    // State encoding
    typedef enum logic [1:0] {
        S0,  // No bits matched
        S1,  // Matched '1'
        S2   // Matched '10'
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        case(rst_n)
            1'b0: current_state <= S0;
            1'b1: current_state <= next_state;
            default: current_state <= S0;
        endcase
    end

    // Combinational block: next state logic
    always_comb begin
        case (current_state)
            S0: case(data_in)
                    1'b1: next_state = S1;
                    1'b0: next_state = S0;
                    default: next_state = S0;
                endcase
            S1: case(data_in)
                    1'b0: next_state = S2;
                    1'b1: next_state = S1;
                    default: next_state = S0;
                endcase
            S2: case(data_in)
                    1'b1: next_state = S1;
                    1'b0: next_state = S0;
                    default: next_state = S0;
                endcase
            default: next_state = S0;
        endcase
    end

    // Combinational block: output logic (Mealy)
    always_comb begin
        case (current_state)
            S2: case(data_in)
                    1'b1: detected = 1'b1;
                    default: detected = 1'b0;
                endcase
            default: detected = 1'b0;
        endcase
    end

endmodule,"module mealy_101_detector (

