module traffic_light_mealy (
    input logic clk,
    input logic rst_n,
    input logic pedestrian_req,
    output logic [1:0] lights,  // 00: Green, 01: Yellow, 10: Red
    output logic walk_signal
);

typedef enum logic [1:0] {GREEN, YELLOW, RED} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case(rst_n)
        1'b0: state <= GREEN;
        1'b1: state <= next_state;
        default: state <= GREEN;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    lights = {2{1'b0}};
    walk_signal = 1'b0;

    case (state)
        GREEN: begin
            lights = 2'b00;  // Green
            case(pedestrian_req)
                1'b1: begin
                    next_state = YELLOW;
                    walk_signal = 1'b1;  // Walk signal triggered immediately
                end
                1'b0: begin
                    next_state = state;
                end
                default: begin
                    next_state = state;
                end
            endcase
        end

        YELLOW: begin
            lights = 2'b01;  // Yellow
            // Count 3 cycles then change to red
            // (simplified - normally would have counter)
            next_state = RED;
        end

        RED: begin
            lights = 2'b10;  // Red
            // After pedestrian crossing time
            next_state = GREEN;
        end
    endcase
end

endmodule,"Here is a Python program that generates the desired SystemVerilog module:

