module runt_pulse_detector (
    input logic clk,
    input logic rst_n,
    input logic signal_in,
    input logic [3:0] min_width,
    output logic runt_detected
);

typedef enum logic [2:0] {IDLE, PULSE_LOW, PULSE_HIGH, CHECK} state_t;
state_t state, next_state;
logic [3:0] pulse_width;

always_ff @(posedge clk or negedge rst_n) begin
    case(rst_n)
        1'b0: begin
            state <= IDLE;
            pulse_width <= 4'b0;
        end
        1'b1: begin
            state <= next_state;
            case(state)
                PULSE_LOW, PULSE_HIGH: pulse_width <= pulse_width + 1;
                default: pulse_width <= 4'b0;
            endcase
        end
        default: begin
            state <= IDLE;
            pulse_width <= 4'b0;
        end
    endcase
end

always_comb begin
    next_state = state;
    runt_detected = 1'b0;

    case (state)
        IDLE: begin
            case(signal_in)
                1'b1: next_state = PULSE_HIGH;
                1'b0: next_state = PULSE_LOW;
                default: next_state = state;
            endcase
        end

        PULSE_HIGH: begin
            case(signal_in)
                1'b0: begin
                    next_state = CHECK;
                    // Check if pulse was too short
                    case(pulse_width < min_width)
                        1'b1: runt_detected = 1'b1;  // Immediate detection
                        1'b0: runt_detected = 1'b0;
                        default: runt_detected = 1'b0;
                    endcase
                end
                1'b1: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
                default: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
            endcase
        end

        PULSE_LOW: begin
            case(signal_in)
                1'b1: begin
                    next_state = CHECK;
                    // Check if pulse was too short
                    case(pulse_width < min_width)
                        1'b1: runt_detected = 1'b1;  // Immediate detection
                        1'b0: runt_detected = 1'b0;
                        default: runt_detected = 1'b0;
                    endcase
                end
                1'b0: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
                default: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
            endcase
        end

        CHECK: begin
            // Return to IDLE after one cycle
            next_state = IDLE;
            runt_detected = 1'b0;
        end

        default: begin
            next_state = IDLE;
            runt_detected = 1'b0;
        end
    endcase
end

endmodule,"module runt_pulse_detector (

module tcp_congestion_control (
    input logic clk,
    input logic rst_n,
    input logic ack_received,
    input logic timeout_event,
    input logic [15:0] rtt_measurement,
    input logic [2:0] duplicate_acks,
    output logic [15:0] congestion_window,
    output logic [15:0] slow_start_threshold,
    output logic [1:0] phase  // 00: SLOW_START, 01: CONG_AVOID, 10: FAST_RECOVERY
);

typedef enum logic [2:0] {
    SLOW_START,
    CONGESTION_AVOIDANCE,
    FAST_RECOVERY,
    FAST_RETRANSMIT,
    TIMEOUT_WAIT,
    PROBE
} state_t;

state_t state, next_state;
logic [15:0] cwnd, next_cwnd;
logic [15:0] ssthresh, next_ssthresh;
logic [3:0] ack_counter, next_ack_counter;
logic [31:0] rto_counter, next_rto_counter;
logic [15:0] min_rtt, next_min_rtt;
logic [15:0] avg_rtt, next_avg_rtt;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= SLOW_START;
            cwnd <= 16'd1;
            ssthresh <= 16'd65535;
            ack_counter <= 4'b0;
            rto_counter <= 32'b0;
            min_rtt <= 16'hFFFF;
            avg_rtt <= 16'd100;
        end
        1'b1: begin
            state <= next_state;
            cwnd <= next_cwnd;
            ssthresh <= next_ssthresh;
            ack_counter <= next_ack_counter;
            rto_counter <= next_rto_counter;
            min_rtt <= next_min_rtt;
            avg_rtt <= next_avg_rtt;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_cwnd = cwnd;
    next_ssthresh = ssthresh;
    next_ack_counter = ack_counter;
    next_rto_counter = rto_counter;
    next_min_rtt = min_rtt;
    next_avg_rtt = avg_rtt;

    congestion_window = cwnd;
    slow_start_threshold = ssthresh;
    phase = 2'b00;

    // Update RTT measurements
    case (rtt_measurement < min_rtt)
      	(1'b1): next_min_rtt = rtt_measurement;
        default: next_min_rtt = min_rtt;
    endcase

    next_avg_rtt = (avg_rtt * 7 + rtt_measurement) >> 3;

    // FSM logic
    case (state)
        SLOW_START: begin
            phase = 2'b00;

            // Check for packet loss
            case (duplicate_acks >= 3'd3)
                1'b1: begin
                    next_state = FAST_RECOVERY;
                    next_ssthresh = cwnd >> 1;
                end
            endcase

            // ACK handling
            case (ack_received)
                1'b1: begin
                    next_cwnd = cwnd + 1;
                    next_ack_counter = ack_counter + 1;
                    case (cwnd >= ssthresh)
                        1'b1: next_state = CONGESTION_AVOIDANCE;
                    endcase
                end
            endcase

            // RTT-based adaptation
            case (rtt_measurement > (avg_rtt + (avg_rtt >> 2)))
                1'b1: begin
                    next_ssthresh = cwnd;
                    next_state = CONGESTION_AVOIDANCE;
                end
            endcase
        end

        CONGESTION_AVOIDANCE: begin
            phase = 2'b01;

            // Packet loss detection
            case (duplicate_acks == 3'd3)
                1'b1: begin
                    next_state = FAST_RETRANSMIT;
                    next_ssthresh = cwnd >> 1;
                    next_cwnd = next_ssthresh + 3;
                end
            endcase

            // ACK handling
            case (ack_received)
                1'b1: begin
                    next_ack_counter = ack_counter + 1;
                    case (ack_counter == cwnd)
                        1'b1: begin
                            next_cwnd = cwnd + 1;
                            next_ack_counter = 4'b0;
                        end
                    endcase
                end
            endcase

            // Timeout handling
            case (timeout_event)
                1'b1: begin
                    next_ssthresh = cwnd >> 1;
                    next_cwnd = 16'd1;
                    next_state = TIMEOUT_WAIT;
                    next_rto_counter = 32'b0;
                end
            endcase
        end

        FAST_RECOVERY: begin
            phase = 2'b10;

            case (ack_received)
                1'b1: begin
                    next_cwnd = ssthresh;
                    next_state = CONGESTION_AVOIDANCE;
                end
            endcase

            case (duplicate_acks == 3'd3)
                1'b1: begin
                    next_state = FAST_RETRANSMIT;
                    next_ssthresh = cwnd >> 1;
                    next_cwnd = next_ssthresh + 3;
                end
            endcase
        end

        FAST_RETRANSMIT: begin
            phase = 2'b10;

            case (ack_received)
                1'b1: next_state = FAST_RECOVERY;
            endcase
        end

        TIMEOUT_WAIT: begin
            phase = 2'b00;

            next_rto_counter = rto_counter + 1;
            case ((rto_counter > (min_rtt * 2)) && ack_received)
                1'b1: next_state = SLOW_START;
                1'b0: begin
                    case ((rto_counter > (min_rtt * 2)) && !ack_received)
                        1'b1: next_state = PROBE;
                    endcase
                end
            endcase
        end

        PROBE: begin
            phase = 2'b00;

            next_cwnd = 16'd1;
            case (ack_received)
                1'b1: next_state = SLOW_START;
            endcase
        end
    endcase
end

endmodule,"module tcp_congestion_control (

module spi_master_mealy (
    input logic clk,
    input logic rst_n,
    input logic start,
    input logic [7:0] tx_data,
    output logic sclk,
    output logic mosi,
    input logic miso,
    output logic [7:0] rx_data,
    output logic busy,
    output logic done
);

typedef enum logic [2:0] {IDLE, CLK_LOW, CLK_HIGH, DONE_ST} state_t;
state_t state, next_state;
logic [2:0] bit_count, next_bit_count;
logic [7:0] shift_reg, next_shift_reg;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= IDLE;
            bit_count <= 3'b0;
            shift_reg <= 8'b0;
        end
        1'b1: begin
            state <= next_state;
            bit_count <= next_bit_count;
            shift_reg <= next_shift_reg;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_bit_count = bit_count;
    next_shift_reg = shift_reg;
    sclk = 1'b0;
    mosi = 1'b0;
    busy = 1'b1;
    done = 1'b0;
    rx_data = shift_reg;

    case (state)
        IDLE: begin
            busy = 1'b0;
            done = 1'b0;
            case (start)
                1'b1: begin
                    next_state = CLK_LOW;
                    next_shift_reg = tx_data;
                    next_bit_count = 3'b0;
                end
            endcase
        end

        CLK_LOW: begin
            // SCLK low phase
            sclk = 1'b0;
            mosi = shift_reg[7];  // Output MSB first

            case (bit_count == 3'b111)  // Last bit?
                1'b1: begin
                    // Last bit: sample final data and go to DONE
                    next_shift_reg = {shift_reg[6:0], miso};
                    next_state = DONE_ST;
                end
                1'b0: begin
                    // Sample MISO on rising edge (during CLK_LOW to CLK_HIGH transition)
                    next_shift_reg = {shift_reg[6:0], miso};
                    next_bit_count = bit_count + 1;
                    next_state = CLK_HIGH;
                end
            endcase
        end

        CLK_HIGH: begin
            // SCLK high phase
            sclk = 1'b1;
            mosi = shift_reg[7];  // Continue outputting same bit

            // Mealy output: Data is stable during high phase
            next_state = CLK_LOW;
        end

        DONE_ST: begin
            done = 1'b1;  // Mealy output: done signal
            busy = 1'b0;
            rx_data = shift_reg;
            case (start)
                1'b0: next_state = IDLE;  // Return to idle when start cleared
                default: next_state = DONE_ST;
            endcase
        end
    endcase
end

endmodule,"module spi_master_mealy (

module mealy_traffic_controller (
    input  logic clk,
    input  logic rst_n,
    input  logic timer_expired,
    input  logic pedestrian_req,
    output logic main_green,
    output logic main_yellow,
    output logic main_red,
    output logic walk,
    output logic dont_walk
);

    // State encoding
    typedef enum logic [1:0] {
        GREEN,      // Main road green
        YELLOW,     // Main road yellow
        RED,        // Main road red
        PED_WALK    // Pedestrian walking
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= GREEN;
            1'b1: current_state <= next_state;
        endcase
    end

    // Combinational block: next state logic with timing conditions
    always_comb begin
        next_state = current_state;

        case (current_state)
            GREEN: begin
                // Go to yellow when timer expires OR pedestrian request
                case (timer_expired || pedestrian_req)
                    1'b1: next_state = YELLOW;
                endcase
            end

            YELLOW: begin
                // Always go to red after yellow timer expires
                case (timer_expired)
                    1'b1: next_state = RED;
                endcase
            end

            RED: begin
                // Go to pedestrian walk if request pending
                case (pedestrian_req)
                    1'b1: next_state = PED_WALK;
                endcase

                case (timer_expired && !pedestrian_req)
                    1'b1: next_state = GREEN;
                endcase
            end

            PED_WALK: begin
                // Return to green after walk timer expires
                case (timer_expired)
                    1'b1: next_state = GREEN;
                endcase
            end
        endcase
    end

    // Combinational block: Mealy outputs based on state and inputs
    always_comb begin
        // Default outputs (all inactive)
        {main_green, main_yellow, main_red} = 3'b000;
        {walk, dont_walk} = 2'b00;

        case (current_state)
            GREEN: begin
                main_green = 1'b1;
                dont_walk = 1'b1;  // Don't walk during main traffic
                // Mealy: Flash don't walk when pedestrian waiting
                case (pedestrian_req)
                    1'b1: dont_walk = ~dont_walk;  // Flashing indication
                endcase
            end

            YELLOW: begin
                main_yellow = 1'b1;
                dont_walk = 1'b1;
            end

            RED: begin
                main_red = 1'b1;
                // Mealy: Pre-walk indication when pedestrian waiting
                case (pedestrian_req)
                    1'b1: dont_walk = ~dont_walk;  // Flashing before walk
                    1'b0: dont_walk = 1'b1;
                endcase
            end

            PED_WALK: begin
                main_red = 1'b1;
                walk = 1'b1;        // Walk signal active
            end
        endcase
    end

endmodule,"module mealy_traffic_controller (

// AXI4-Lite Slave Interface - Register File Example
// Uses only case statements (no if/else)
// Demonstrates separate combinational and sequential logic blocks

module axi_lite_slave (
    // Clock and Reset
    input  logic        aclk,
    input  logic        aresetn,

    // AXI4-Lite Write Address Channel
    input  logic [31:0] s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    // AXI4-Lite Write Data Channel
    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    // AXI4-Lite Write Response Channel
    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    // AXI4-Lite Read Address Channel
    input  logic [31:0] s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    // AXI4-Lite Read Data Channel
    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready,

    // User interface to registers
    output logic [31:0] reg0,  // Read/Write register
    output logic [31:0] reg1,  // Read/Write register
    output logic [31:0] reg2,  // Read/Write register
    output logic [31:0] reg3,  // Read/Write register
    input  logic [31:0] reg4   // Read-only register
);

    //=========================================================
    // Internal State Definitions
    //=========================================================
    typedef enum logic [1:0] {
        IDLE,
        WRITE_RESP,
        READ_DATA
    } state_t;

    state_t write_state, read_state;
    state_t write_state_next, read_state_next;

    //=========================================================
    // Register Storage
    //=========================================================
    logic [31:0] reg0_q, reg1_q, reg2_q, reg3_q;
    logic [31:0] reg0_next, reg1_next, reg2_next, reg3_next;

    //=========================================================
    // AXI Interface Registers
    //=========================================================
    logic        awready_q, awready_next;
    logic        wready_q, wready_next;
    logic        bvalid_q, bvalid_next;
    logic [1:0]  bresp_q, bresp_next;

    logic        arready_q, arready_next;
    logic        rvalid_q, rvalid_next;
    logic [1:0]  rresp_q, rresp_next;
    logic [31:0] rdata_q, rdata_next;

    // Address and data storage for transactions
    logic [31:0] awaddr_q, awaddr_next;
    logic [31:0] wdata_q, wdata_next;
    logic [3:0]  wstrb_q, wstrb_next;
    logic [31:0] araddr_q, araddr_next;

    //=========================================================
    // Combinational Logic: Write Channel FSM
    //=========================================================
    always_comb begin
        // Default assignments
        write_state_next = write_state;
        awready_next = 1'b0;
        wready_next  = 1'b0;
        bvalid_next  = bvalid_q;
        bresp_next   = bresp_q;
        awaddr_next  = awaddr_q;
        wdata_next   = wdata_q;
        wstrb_next   = wstrb_q;
        reg0_next = reg0_q;
        reg1_next = reg1_q;
        reg2_next = reg2_q;
        reg3_next = reg3_q;

        case (write_state)
            IDLE: begin
                awready_next = 1'b1;
                wready_next  = 1'b1;

                // Capture address and data when valid
                case ({s_axi_awvalid, s_axi_wvalid})
                    2'b11: begin
                        awaddr_next = s_axi_awaddr;
                        wdata_next  = s_axi_wdata;
                        wstrb_next  = s_axi_wstrb;
                        write_state_next = WRITE_RESP;
                    end
                    default: begin
                        write_state_next = IDLE;
                    end
                endcase
            end

            WRITE_RESP: begin
                bvalid_next = 1'b1;
                bresp_next  = 2'b00;  // OKAY response

                // Perform register write based on address
                case (awaddr_q[7:2])  // 4-byte aligned addresses
                    6'b000000: begin  // Address 0x00
                        reg0_next = wdata_q;
                    end
                    6'b000001: begin  // Address 0x04
                        reg1_next = wdata_q;
                    end
                    6'b000010: begin  // Address 0x08
                        reg2_next = wdata_q;
                    end
                    6'b000011: begin  // Address 0x0C
                        reg3_next = wdata_q;
                    end
                    default: begin
                        // Invalid address - no write
                        bresp_next = 2'b11;  // SLVERR
                    end
                endcase

                case ({bvalid_q, s_axi_bready})
                    2'b11: begin
                        bvalid_next = 1'b0;
                        write_state_next = IDLE;
                    end
                    default: begin
                        write_state_next = WRITE_RESP;
                    end
                endcase
            end
        endcase
    end

    //=========================================================
    // Combinational Logic: Read Channel FSM
    //=========================================================
    always_comb begin
        // Default assignments
        read_state_next = read_state;
        arready_next = 1'b0;
        rvalid_next  = rvalid_q;
        rresp_next   = rresp_q;
        rdata_next   = rdata_q;
        araddr_next  = araddr_q;

        case (read_state)
            IDLE: begin
                arready_next = 1'b1;

                case (s_axi_arvalid)
                    1'b1: begin
                        araddr_next = s_axi_araddr;
                        read_state_next = READ_DATA;
                    end
                    default: begin
                        read_state_next = IDLE;
                    end
                endcase
            end

            READ_DATA: begin
                rvalid_next = 1'b1;
                rresp_next  = 2'b00;  // OKAY response

                // Read data based on address
                case (araddr_q[7:2])  // 4-byte aligned addresses
                    6'b000000: begin  // Address 0x00
                        rdata_next = reg0_q;
                    end
                    6'b000001: begin  // Address 0x04
                        rdata_next = reg1_q;
                    end
                    6'b000010: begin  // Address 0x08
                        rdata_next = reg2_q;
                    end
                    6'b000011: begin  // Address 0x0C
                        rdata_next = reg3_q;
                    end
                    6'b000100: begin  // Address 0x10
                        rdata_next = reg4;  // Read-only register
                    end
                    default: begin
                        rdata_next = 32'hDEADBEEF;
                        rresp_next = 2'b11;  // SLVERR
                    end
                endcase

                case ({rvalid_q, s_axi_rready})
                    2'b11: begin
                        rvalid_next = 1'b0;
                        read_state_next = IDLE;
                    end
                    default: begin
                        read_state_next = READ_DATA;
                    end
                endcase
            end
        endcase
    end

    //=========================================================
    // Output Assignments
    //=========================================================
    assign s_axi_awready = awready_q;
    assign s_axi_wready  = wready_q;
    assign s_axi_bvalid  = bvalid_q;
    assign s_axi_bresp   = bresp_q;

