    assign s_axi_rresp   = rresp_q;
    assign s_axi_rdata   = rdata_q;

    assign reg0 = reg0_q;
    assign reg1 = reg1_q;
    assign reg2 = reg2_q;
    assign reg3 = reg3_q;

