module uart_sampler_mealy (
    input logic clk,
    input logic rst_n,
    input logic rx_line,
    input logic sample_enable,
    output logic bit_value,
    output logic bit_ready
);

typedef enum logic [2:0] {IDLE, START, MIDDLE, SAMPLE} state_t;
state_t state, next_state;
logic [2:0] oversample_count, next_oversample_count;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= IDLE;
            oversample_count <= 3'b0;
        end
        1'b1: begin
            state <= next_state;
            oversample_count <= next_oversample_count;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_oversample_count = oversample_count;
    bit_value = 1'b0;
    bit_ready = 1'b0;

    // Counter increment logic
    case (sample_enable)
        1'b1: next_oversample_count = oversample_count + 1;
        default: next_oversample_count = oversample_count;
    endcase

    case (state)
        IDLE: begin
            case (!rx_line && sample_enable)  // Start bit detected
                1'b1: next_state = START;
            endcase
        end

        START: begin
            case (sample_enable)
                1'b1: begin
                    case (oversample_count == 3'b100)  // Middle of start bit
                        1'b1: next_state = MIDDLE;
                    endcase
                end
            endcase
        end

        MIDDLE: begin
            case (sample_enable)
                1'b1: begin
                    case (oversample_count == 3'b111)  // Sample point
                        1'b1: begin
                            next_state = SAMPLE;
                            bit_value = rx_line;  // Mealy: sample the bit
                            bit_ready = 1'b1;     // Mealy: bit ready immediately
                        end
                    endcase
                end
            endcase
        end

        SAMPLE: begin
            case (sample_enable)
                1'b1: begin
                    case (oversample_count == 3'b111)
                        1'b1: next_state = IDLE;
                        1'b0: next_state = MIDDLE;
                    endcase
                end
            endcase
        end
    endcase
end

