                        master_ack = 4'b1000;
                    end
                    default: begin
                        master_rdata = '{default: '0};
                        master_ack = 4'b0000;
                    end
                endcase
            end

            default: begin
                master_grant = 4'b0000;
                master_ack = 4'b0000;
                master_rdata = '{default: '0};
                mem_cs = 1'b0;
                mem_we = 1'b0;
            end
        endcase
    end

